package io.knowledgebrain.knowledge;
import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;import jakarta.servlet.http.HttpServletRequest;
import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
/** Narrow canonical event recovery. Knowledge owns and reads only its own Outbox. */
@RestController @ConditionalOnProperty(name="brain.knowledge.activity-export.enabled",havingValue="true")
final class ActivityExportController {
 private static ResponseStatusException bad(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid activity export request");}
 record Item(UUID eventId,String topic,String payload){}record Page(UUID through,UUID nextAfter,List<Item> items){}
 private final JdbcTemplate jdbc;private final byte[] key;private final MeterRegistry metrics;
 ActivityExportController(DataSource ds,@Value("${brain.knowledge.activity-export.key}")String key,MeterRegistry metrics){if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Scoped export key required");jdbc=new JdbcTemplate(ds);this.key=("Bearer "+key).getBytes(StandardCharsets.US_ASCII);this.metrics=metrics;}
 @GetMapping("/internal/knowledge/activity-events") ResponseEntity<Page> page(@RequestParam(required=false)UUID after,@RequestParam(required=false)UUID through,HttpServletRequest r){var auth=Collections.list(r.getHeaders("Authorization"));if(!r.isSecure()||auth.size()!=1||!MessageDigest.isEqual(key,auth.getFirst().getBytes(StandardCharsets.UTF_8))||r.getHeader("Cookie")!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Scoped service authority required");for(var p:r.getParameterMap().entrySet())if(!Set.of("after","through").contains(p.getKey())||p.getValue().length!=1)throw bad();if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw bad();if(after!=null)ConceptStore.id(after);if(through!=null)ConceptStore.id(through);if(through==null){var max=jdbc.queryForList("SELECT id FROM outbox_event WHERE schema_group='knowledge' AND schema_version='1' AND ((aggregatetype='claim' AND schema_artifact='claim-events') OR (aggregatetype='claim-v2' AND schema_artifact='claim-events-v2')) ORDER BY id DESC LIMIT 1",UUID.class);through=max.isEmpty()?null:max.getFirst();}if(after!=null&&(through==null||after.toString().compareTo(through.toString())>0))throw bad();List<Item> rows=through==null?List.of():jdbc.query("SELECT id,aggregatetype,payload FROM outbox_event WHERE schema_group='knowledge' AND schema_version='1' AND ((aggregatetype='claim' AND schema_artifact='claim-events') OR (aggregatetype='claim-v2' AND schema_artifact='claim-events-v2')) AND id<=?"+(after==null?"":" AND id>?")+" ORDER BY id LIMIT 6",(rs,n)->new Item(rs.getObject(1,UUID.class),rs.getString(2).equals("claim")?"knowledge.claim.v1":"knowledge.claim.v2",Base64.getEncoder().encodeToString(rs.getBytes(3))),after==null?new Object[]{through}:new Object[]{through,after});var items=List.copyOf(rows.subList(0,Math.min(rows.size(),5)));metrics.counter("brain.knowledge.activity.exports").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(through,rows.size()>5?items.getLast().eventId():null,items));}
}
